#!/usr/bin/env node
/**
 * Bundles the audio analysis worker (src/lib/audio/analysis.worker.ts and the pure analysis
 * core it imports) into public/workers/analysis.worker.js, which the import screen starts
 * with `new Worker(..., { type: "module" })`. Turbopack in Next 16.3.6 copies a
 * `new URL("./x.ts", import.meta.url)` worker as a raw asset instead of bundling it, so the
 * bundle is built here and committed, like the repo's other generated files.
 *
 * Usage: node scripts/build-analysis-worker.mjs            write the bundle
 *        node scripts/build-analysis-worker.mjs --check    exit 1 if it is out of date
 */
import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname } from "node:path";
import { fileURLToPath } from "node:url";

import { rolldown } from "rolldown";

const root = fileURLToPath(new URL("..", import.meta.url));
const OUT = "public/workers/analysis.worker.js";

export async function buildWorker() {
  const bundle = await rolldown({ input: `${root}src/lib/audio/analysis.worker.ts`, cwd: root, platform: "browser", logLevel: "silent" });
  const { output } = await bundle.generate({ format: "esm" });
  await bundle.close();
  const header = "// EVAWAVE audio analysis worker. Generated by scripts/build-analysis-worker.mjs from\n// src/lib/audio/analysis.worker.ts; do not edit.\n";
  return header + output[0].code;
}

if (import.meta.url === `file://${process.argv[1]}`) {
  const code = await buildWorker();
  if (process.argv.includes("--check")) {
    let current = "";
    try {
      current = readFileSync(`${root}${OUT}`, "utf8");
    } catch {
      // Missing counts as out of date.
    }
    if (current !== code) {
      console.error(`${OUT} is out of date. Run node scripts/build-analysis-worker.mjs`);
      process.exit(1);
    }
    console.log(`${OUT} matches its source`);
  } else {
    mkdirSync(`${root}${dirname(OUT)}`, { recursive: true });
    writeFileSync(`${root}${OUT}`, code);
    console.log(`wrote ${OUT}`);
  }
}
